sys_script_include.script:
var AttendeeEventUtils  = Class.create();
AttendeeEventUtils .prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
getEventDetails: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('x_1790233_event_ma_event_record');
        if (gr.get(eventId)) {
            return new JSON().encode({
                name: gr.getValue('event_name'),
                date: gr.getValue('event_date'),
                location: gr.getValue('location')
            });
        }
        return '';
    },
    type: 'AttendeeEventUtils '
});
